(function( $ ) {

	'use strict';

	var BewBuilderData = window.BewBuilderData || {},
		BewBuilderEditor,
		BewBuilderViews,
		BewBuilderControlsViews,
		BewBuilderModules;

	BewBuilderViews = {

		LibraryLayoutView: null,
		LibraryHeaderView: null,
		LibraryLoadingView: null,
		LibraryErrorView: null,
		LibraryBodyView: null,
		LibraryCollectionView: null,
		FiltersCollectionView: null,
		LibraryTabsCollectionView: null,
		LibraryTabsItemView: null,
		FiltersItemView: null,
		LibraryTemplateItemView: null,
		LibraryInsertTemplateBehavior: null,
		LibraryTabsCollection: null,
		LibraryCollection: null,
		CategoriesCollection: null,
		LibraryTemplateModel: null,
		CategoryModel: null,
		TabModel: null,
		KeywordsModel: null,
		KeywordsView: null,
		LibraryPreviewView: null,
		LibraryHeaderBack: null,
		LibraryHeaderInsertButton: null,

		init: function() {

			var self = this;

			self.LibraryTemplateModel = Backbone.Model.extend( {
				defaults: {
					template_id: 0,
					name: '',
					title: '',
					thumbnail: '',
					preview: '',
					source: '',
					categories: [],
					keywords: []
				}
			} );

			self.CategoryModel = Backbone.Model.extend( {
				defaults: {
					slug: '',
					title: ''
				}
			} );

			self.CategoryModel = Backbone.Model.extend( {
				defaults: {
					slug: '',
					title: ''
				}
			} );

			self.TabModel = Backbone.Model.extend( {
				defaults: {
					slug: '',
					title: ''
				}
			} );

			self.KeywordsModel = Backbone.Model.extend( {
				defaults: {
					keywords: {}
				}
			} );

			self.LibraryCollection = Backbone.Collection.extend( {
				model: self.LibraryTemplateModel
			} );

			self.CategoriesCollection = Backbone.Collection.extend( {
				model: self.CategoryModel
			} );

			self.LibraryTabsCollection = Backbone.Collection.extend( {
				model: self.TabModel
			} );

			self.LibraryLoadingView = Marionette.ItemView.extend( {
				id: 'bew-template-library-loading',
				template: '#tmpl-bew-template-library-loading'
			} );

			self.LibraryErrorView = Marionette.ItemView.extend( {
				id: 'bew-template-library-error',
				template: '#tmpl-bew-template-library-error'
			} );

			self.KeywordsView = Marionette.ItemView.extend( {
				id: 'bew-template-library-keywords',
				template: '#tmpl-bew-template-library-keywords',
				ui: {
					keywords: '.bew-library-keywords'
				},

				events: {
					'change @ui.keywords': 'onSelectKeyword'
				},

				onSelectKeyword: function( event ) {
					var selected = event.currentTarget.selectedOptions[0].value;
					BewBuilderEditor.setFilter( 'keyword', selected );
				}
			} );

			self.LibraryHeaderView = Marionette.LayoutView.extend( {

				id: 'bew-template-library-header',
				template: '#tmpl-bew-template-library-header',

				ui: {
					closeModal: '#bew-template-library-header-close-modal'
				},

				events: {
					'click @ui.closeModal': 'onCloseModalClick'
				},

				regions: {
					headerTabs: '#bew-template-library-header-tabs',
					headerActions: '#bew-template-library-header-actions'
				},

				onCloseModalClick: function() {
					BewBuilderEditor.closeModal();
				}

			} );

			self.LibraryPreviewView = Marionette.ItemView.extend( {

				template: '#tmpl-bew-template-library-preview',

				id: 'bew-template-library-preview',

				ui: {
					img: 'img'
				},

				onRender: function() {
					this.ui.img.attr( 'src', this.getOption( 'preview' ) );
				}
			} );

			self.LibraryHeaderBack = Marionette.ItemView.extend( {

				template: '#tmpl-bew-template-library-header-back',

				id: 'bew-template-library-header-back',

				ui: {
					button: 'button'
				},

				events: {
					'click @ui.button': 'onBackClick',
				},

				onBackClick: function() {
					BewBuilderEditor.setPreview( 'back' );
				}

			} );

			self.LibraryInsertTemplateBehavior = Marionette.Behavior.extend( {
				ui: {
					insertButton: '.bew-template-library-template-insert'
				},

				events: {
					'click @ui.insertButton': 'onInsertButtonClick'
				},

				onInsertButtonClick: function() {

					var templateModel = this.view.model,
						options       = {};

					BewBuilderEditor.layout.showLoadingView();

					elementor.templates.requestTemplateContent(
						templateModel.get( 'source' ),
						templateModel.get( 'template_id' ),
						{
							data: {
								tab: BewBuilderEditor.getTab(),
								page_settings: true
							},
							success: function( data ) {

								if ( data.licenseError ) {
									BewBuilderEditor.layout.showLicenseError();
									return;
								}

								BewBuilderEditor.closeModal();

								elementor.channels.data.trigger( 'template:before:insert', templateModel );

								if ( null !== BewBuilderEditor.atIndex ) {
									options.at = BewBuilderEditor.atIndex;
								}

								if ( elementor.sections ) {
									elementor.sections.currentView.addChildModel( data.content, options );
								} else {
									elementor.getPreviewView().addChildModel( data.content, options ); // For compat with Elementor 3.0
								}

								if ( data.page_settings ) {
									elementor.settings.page.model.set( data.page_settings );
								}

								elementor.channels.data.trigger( 'template:after:insert', templateModel );

								BewBuilderEditor.atIndex = null;

								if ( $e ) {
									$e.run( 'document/save/update' );
								}

							}
						}
					);
				}
			} );

			self.LibraryHeaderInsertButton = Marionette.ItemView.extend( {

				template: '#tmpl-bew-template-library-insert-button',

				id: 'bew-template-library-insert-button',

				behaviors: {
					insertTemplate: {
						behaviorClass: self.LibraryInsertTemplateBehavior
					}
				}

			} );

			self.LibraryTemplateItemView = Marionette.ItemView.extend( {

				template: '#tmpl-bew-template-library-item',

				className: function() {

					var urlClass    = ' bew-template-has-url',
						sourceClass = ' elementor-template-library-template-';

					if ( '' === this.model.get( 'preview' ) ) {
						urlClass = ' bew-template-no-url';
					}

					if ( 'bew-local' === this.model.get( 'source' ) ) {
						sourceClass += 'local';
					} else {
						sourceClass += 'remote';
					}

					return 'elementor-template-library-template' + sourceClass + urlClass;
				},

				ui: function() {
					return {
						previewButton: '.elementor-template-library-template-preview',
						cloneButton: '.bew-clone-to-library',
					};
				},

				events: function() {
					return {
						'click @ui.previewButton': 'onPreviewButtonClick',
						'click @ui.cloneButton': 'onCloneButtonClick'
					};
				},

				onPreviewButtonClick: function() {

					if ( '' === this.model.get( 'preview' ) ) {
						return;
					}

					BewBuilderEditor.setPreview( this.model );
				},

				onCloneButtonClick: function() {

					BewBuilderEditor.layout.showLoadingView();

					$.ajax({
						url: ajaxurl,
						type: 'post',
						dataType: 'json',
						data: {
							action:  'bew_builder_clone_template',
							template: this.model.attributes,
							tab: BewBuilderEditor.getTab()
						}
					}).done( function( response ) {
						if ( true === response.success ) {
							BewBuilderEditor.channels.layout.trigger( 'template:cloned' );
							BewBuilderEditor.tabs.local.data = {};
							BewBuilderEditor.setTab( 'local' );
						} else {
							BewBuilderEditor.setTab( BewBuilderEditor.getTab() );
						}
					});

				},

				behaviors: {
					insertTemplate: {
						behaviorClass: self.LibraryInsertTemplateBehavior
					}
				}
			} );

			self.FiltersItemView = Marionette.ItemView.extend( {

				template: '#tmpl-bew-template-library-filters-item',

				className: function() {
					return 'bew-filter-item';
				},

				ui: function() {
					return {
						filterLabels: '.bew-template-library-filter-label'
					};
				},

				events: function() {
					return {
						'click @ui.filterLabels': 'onFilterClick'
					};
				},

				onFilterClick: function( event ) {

					var $clickedInput = jQuery( event.target );

					BewBuilderEditor.setFilter( 'category', $clickedInput.val() );
				}

			} );

			self.LibraryTabsItemView = Marionette.ItemView.extend( {

				template: '#tmpl-bew-template-library-tabs-item',

				className: function() {
					return 'elementor-template-library-menu-item';
				},

				ui: function() {
					return {
						tabsLabels: 'label',
						tabsInput: 'input'
					};
				},

				events: function() {
					return {
						'click @ui.tabsLabels': 'onTabClick'
					};
				},

				onRender: function() {
					if ( this.model.get( 'slug' ) === BewBuilderEditor.getTab() ) {
						this.ui.tabsInput.attr( 'checked', 'checked' );
					}
				},

				onTabClick: function( event ) {

					var $clickedInput = jQuery( event.target );
					BewBuilderEditor.setTab( $clickedInput.val() );
					BewBuilderEditor.setFilter( 'keyword', '' );
				}

			} );

			self.LibraryCollectionView = Marionette.CompositeView.extend( {

				template: '#tmpl-bew-template-library-templates',

				id: 'bew-template-library-templates',

				childViewContainer: '#bew-template-library-templates-container',

				initialize: function() {
					this.listenTo( BewBuilderEditor.channels.templates, 'filter:change', this._renderChildren );
				},

				filter: function( childModel ) {

					var filter  = BewBuilderEditor.getFilter( 'category' ),
						keyword = BewBuilderEditor.getFilter( 'keyword' );

					if ( ! filter && ! keyword ) {
						return true;
					}

					if ( keyword && ! filter ) {
						return _.contains( childModel.get( 'keywords' ), keyword );
					}

					if ( filter && ! keyword ) {
						return _.contains( childModel.get( 'categories' ), filter );
					}

					return _.contains( childModel.get( 'categories' ), filter ) && _.contains( childModel.get( 'keywords' ), keyword );

				},

				getChildView: function( childModel ) {
					return self.LibraryTemplateItemView;
				},

				onRenderCollection: function() {

					var container = this.$childViewContainer,
						items     = this.$childViewContainer.children(),
						tab       = BewBuilderEditor.getTab();

					if ( 'bew_page' === tab || 'local' === tab ) {
						return;
					}

					setTimeout( function() {
						self.masonry.init({
							container: container,
							items: items,
						});
					}, 200 );

				}

			} );

			self.LibraryTabsCollectionView = Marionette.CompositeView.extend( {

				template: '#tmpl-bew-template-library-tabs',

				childViewContainer: '#bew-template-library-tabs-items',

				initialize: function() {
					this.listenTo( BewBuilderEditor.channels.layout, 'tamplate:cloned', this._renderChildren );
				},

				getChildView: function( childModel ) {
					return self.LibraryTabsItemView;
				}

			} );

			self.FiltersCollectionView = Marionette.CompositeView.extend( {

				id: 'bew-template-library-filters',

				template: '#tmpl-bew-template-library-filters',

				childViewContainer: '#bew-template-library-filters-container',

				getChildView: function( childModel ) {
					return self.FiltersItemView;
				}

			} );

			self.LibraryBodyView = Marionette.LayoutView.extend( {

				id: 'bew-template-library-content',

				className: function() {
					return 'library-tab-' + BewBuilderEditor.getTab();
				},

				template: '#tmpl-bew-template-library-content',

				regions: {
					contentTemplates: '.bew-templates-list',
					contentFilters: '.bew-filters-list',
					contentKeywords: '.bew-keywords-list'
				}

			} );

			self.LibraryLayoutView = Marionette.LayoutView.extend( {

				el: '#bew-template-library-modal',

				regions: BewBuilderData.modalRegions,

				initialize: function() {

					this.getRegion( 'modalHeader' ).show( new self.LibraryHeaderView() );
					this.listenTo( BewBuilderEditor.channels.tabs, 'filter:change', this.switchTabs );
					this.listenTo( BewBuilderEditor.channels.layout, 'preview:change', this.switchPreview );

				},

				switchTabs: function() {
					this.showLoadingView();
					BewBuilderEditor.setFilter( 'keyword', '' );
					BewBuilderEditor.requestTemplates( BewBuilderEditor.getTab() );
				},

				switchPreview: function() {

					var header  = this.getHeaderView(),
						preview = BewBuilderEditor.getPreview();

					if ( 'back' === preview ) {

						header.headerTabs.show( new self.LibraryTabsCollectionView( {
							collection: BewBuilderEditor.collections.tabs
						} ) );

						header.headerActions.empty();

						BewBuilderEditor.setTab( BewBuilderEditor.getTab() );
						return;
					}

					if ( 'initial' === preview ) {
						header.headerActions.empty();
						return;
					}

					this.getRegion( 'modalContent' ).show( new self.LibraryPreviewView( {
						'preview': preview.get( 'preview' )
					} ) );

					header.headerTabs.show( new self.LibraryHeaderBack() );
					header.headerActions.show( new self.LibraryHeaderInsertButton( {
						model: preview
					} ) );

				},

				getHeaderView: function() {
					return this.getRegion( 'modalHeader' ).currentView;
				},

				getContentView: function() {
					return this.getRegion( 'modalContent' ).currentView;
				},

				showLoadingView: function() {
					this.modalContent.show( new self.LibraryLoadingView() );
				},

				showLicenseError: function() {
					this.modalContent.show( new self.LibraryErrorView() );
				},

				showTemplatesView: function( templatesCollection, categoriesCollection, keywords ) {

					this.getRegion( 'modalContent' ).show( new self.LibraryBodyView() );

					var contentView   = this.getContentView(),
						header        = this.getHeaderView(),
						keywordsModel = new self.KeywordsModel( {
							keywords: keywords
						} );

					BewBuilderEditor.collections.tabs = new self.LibraryTabsCollection( BewBuilderEditor.getTabs() );

					header.headerTabs.show( new self.LibraryTabsCollectionView( {
						collection: BewBuilderEditor.collections.tabs
					} ) );

					contentView.contentTemplates.show( new self.LibraryCollectionView( {
						collection: templatesCollection
					} ) );

					contentView.contentFilters.show( new self.FiltersCollectionView( {
						collection: categoriesCollection
					} ) );

					contentView.contentKeywords.show( new self.KeywordsView( { model: keywordsModel } ) );

				}

			} );
		},

		masonry: {

			self: {},
			elements: {},

			init: function( settings ) {

				var self = this;
				self.settings = $.extend( self.getDefaultSettings(), settings );
				self.elements = self.getDefaultElements();

				self.run();
			},

			getSettings: function( key ) {
				if ( key ) {
					return this.settings[ key ];
				} else {
					return this.settings;
				}
			},

			getDefaultSettings: function() {
				return {
					container: null,
					items: null,
					columnsCount: 3,
					verticalSpaceBetween: 30
				};
			},

			getDefaultElements: function() {
				return {
					$container: jQuery( this.getSettings( 'container' ) ),
					$items: jQuery( this.getSettings( 'items' ) )
				};
			},

			run: function() {
				var heights = [],
					distanceFromTop = this.elements.$container.position().top,
					settings = this.getSettings(),
					columnsCount = settings.columnsCount;

				distanceFromTop += parseInt( this.elements.$container.css( 'margin-top' ), 10 );

				this.elements.$container.height( '' );

				this.elements.$items.each( function( index ) {
					var row = Math.floor( index / columnsCount ),
						indexAtRow = index % columnsCount,
						$item = jQuery( this ),
						itemPosition = $item.position(),
						itemHeight = $item[0].getBoundingClientRect().height + settings.verticalSpaceBetween;

					if ( row ) {
						var pullHeight = itemPosition.top - distanceFromTop - heights[ indexAtRow ];
						pullHeight -= parseInt( $item.css( 'margin-top' ), 10 );
						pullHeight *= -1;
						$item.css( 'margin-top', pullHeight + 'px' );
						heights[ indexAtRow ] += itemHeight;
					} else {
						heights.push( itemHeight );
					}
				} );

				this.elements.$container.height( Math.max.apply( Math, heights ) );
			}
		}

	};

	BewBuilderControlsViews = {

		BewSearchView: null,

		init: function() {

			var self = this;

			self.BewSearchView = window.elementor.modules.controls.BaseData.extend( {

				hasTitles: false,

				getAjaxUrl: function( action, queryParams ) {
					var query = '';

					if ( queryParams.length > 0 ) {
						$.each( queryParams, function( index, param ) {

							if ( window.elementor.settings.page.model.attributes[ param ] ) {
								query += '&' + param + '=' + window.elementor.settings.page.model.attributes[ param ];
							}
						});
					}

					return ajaxurl + '?action=' + action + query;
				},

				onReady: function() {
					var self        = this,
						action      = this.model.attributes.action,
						queryParams = this.model.attributes.query_params;

					this.ui.select.find( 'option' ).each(function(index, el) {
						$( this ).attr( 'selected', true );
					});

					this.ui.select.select2( {
						ajax: {
							url: function(){
								return self.getAjaxUrl( action, queryParams );
							},
							dataType: 'json'
						},
						placeholder: 'Please enter 3 or more characters',
						minimumInputLength: 3,
						allowClear: true
					} );

					if ( !this.hasTitles ) {
						this.getOptionsTitles();
					}

				},

				getOptionsTitles: function getOptionsTitles() {
					var self        = this,
						action      = this.model.attributes.action,
						queryParams = this.model.attributes.query_params,
						queryIds    = this.getControlValue();

					if ( !queryIds ) {
						return;
					}

					if ( $.isArray( queryIds ) ) {
						queryIds = queryIds.join();
					}

					var url = self.getAjaxUrl( action, queryParams ) + '&ids' + '=' + queryIds;

					$.ajax( {
						url: url,
						dataType: 'json',
						beforeSend: function() {
							self.ui.select.prop( 'disabled', true );
						},
						success: function( response ) {
							self.hasTitles = true;

							self.model.set( 'saved',  self.prepareOptions( response.results ) );
							self.render();
						}
					} );
				},

				prepareOptions: function prepareOptions( options ) {
					var result = {};

					$.each( options, function( index, item ) {
						result[ item.id ] = item.text;
					} );

					return result;
				},

				onBeforeDestroy: function() {

					if ( this.ui.select.data( 'select2' ) ) {
						this.ui.select.select2( 'destroy' );
					}

					this.$el.remove();
				}

			} );

			window.elementor.addControlView( 'bew_search', self.BewSearchView );

		}

	};

	BewBuilderModules = {

		getDataToSave: function( data ) {
			data.id = window.elementor.config.post_id;
			return data;
		},

		init: function() {

			if ( window.elementor.settings.bew_template ) {
				window.elementor.settings.bew_template.getDataToSave = this.getDataToSave;
			}

			if ( window.elementor.settings.bew_page ) {
				window.elementor.settings.bew_page.getDataToSave = this.getDataToSave;
				window.elementor.settings.bew_page.changeCallbacks = {
					custom_header: function() {
						this.save( function() {
							elementor.reloadPreview();

							elementor.once( 'preview:loaded', function() {
								elementor.getPanelView().setPage( 'bew_page_settings' );
							} );
						} );
					},
					custom_footer: function() {
						this.save( function() {
							elementor.reloadPreview();

							elementor.once( 'preview:loaded', function() {
								elementor.getPanelView().setPage( 'bew_page_settings' );
							} );
						} );
					}
				};
			}

		}

	};

	BewBuilderEditor = {

		modal: false,
		layout: false,
		collections: {},
		tabs: {},
		defaultTab: '',
		channels: {},
		atIndex: null,

		init: function() {

			window.elementor.on(
				'preview:loaded',
				window._.bind( BewBuilderEditor.onPreviewLoaded, BewBuilderEditor )
			);

			BewBuilderViews.init();
			BewBuilderControlsViews.init();
			//BewBuilderModules.init();

		},

		onPreviewLoaded: function() {

			this.initMagicButton();

			window.elementor.$previewContents.on(
				'click.addBewTemplate',
				'.add-bew-template',
				_.bind( this.showTemplatesModal, this )
			);

			this.channels = {
				templates: Backbone.Radio.channel( 'BEW_BUILDER_EDITOR:templates' ),
				tabs: Backbone.Radio.channel( 'BEW_BUILDER_EDITOR:tabs' ),
				layout: Backbone.Radio.channel( 'BEW_BUILDER_EDITOR:layout' ),
			};

			this.tabs       = BewBuilderData.tabs;
			this.defaultTab = BewBuilderData.defaultTab;

		},

		initMagicButton: function() {

			var addBewTemplate = '<div class="elementor-add-section-area-button add-bew-template">&nbsp;</div>';

			window.elementor.on( 'document:loaded', function() {
				var $addNewSection = window.elementor.$previewContents.find( '.elementor-add-new-section' ),
					$addNewSectiondrag = window.elementor.$previewContents.find( '.elementor-add-new-section .elementor-add-section-drag-title' ),
					$addBewTemplate;
					
				if ( $addNewSection.length && ($addNewSection.find( '.add-bew-template' ).length == 0 )) {
					$addBewTemplate = $( addBewTemplate ).insertBefore( $addNewSectiondrag );
				}
			} );

			window.elementor.$previewContents.on(
				'click.addBewTemplate',
				'.elementor-editor-section-settings .elementor-editor-element-add',
				function() {

					var $this    = $( this ),
						$section = $this.closest( '.elementor-top-section' ),
						modelID  = $section.data( 'model-cid' ),
						models   = null;

					if ( window.elementor.sections && window.elementor.sections.currentView.collection.length ) {
						models = window.elementor.sections.currentView.collection.models
					} else if ( elementor.getPreviewView().collection.length ) { // For compat with Elementor 3.0
						models = elementor.getPreviewView().collection.models;
					}

					if ( models ) {
						$.each( models, function( index, model ) {
							if ( modelID === model.cid ) {
								BewBuilderEditor.atIndex = index;
							}
						});
					}

						setTimeout( function() {
							var $addNew = $section.prev( '.elementor-add-section' ).find( '.elementor-add-new-section' ),
								$addNewdrag = $section.prev( '.elementor-add-section' ).find( '.elementor-add-new-section .elementor-add-section-drag-title' );
							$( addBewTemplate ).insertBefore( $addNewdrag );							
						}, 100 );

				}
			);
		},

		getFilter: function( name ) {
			return this.channels.templates.request( 'filter:' + name );
		},

		setFilter: function( name, value ) {
			this.channels.templates.reply( 'filter:' + name, value );
			this.channels.templates.trigger( 'filter:change' );
		},

		getTab: function() {
			return this.channels.tabs.request( 'filter:tabs' );
		},

		setTab: function( value, silent ) {

			this.channels.tabs.reply( 'filter:tabs', value );

			if ( ! silent ) {
				this.channels.tabs.trigger( 'filter:change' );
			}

		},

		getTabs: function() {

			var tabs = [];

			_.each( this.tabs, function( item, slug ) {
				tabs.push({
					slug: slug,
					title: item.title
				});
			} );

			return tabs;
		},

		getPreview: function( name ) {
			return this.channels.layout.request( 'preview' );
		},

		setPreview: function( value, silent ) {

			this.channels.layout.reply( 'preview', value );

			if ( ! silent ) {
				this.channels.layout.trigger( 'preview:change' );
			}
		},

		getKeywords: function() {

			var keywords = [];

			_.each( this.keywords, function( title, slug ) {
				tabs.push({
					slug: slug,
					title: title
				});
			} );

			return keywords;
		},

		showTemplatesModal: function() {

			this.getModal().show();

			if ( ! this.layout ) {
				this.layout = new BewBuilderViews.LibraryLayoutView();
				this.layout.showLoadingView();
			}

			this.setTab( this.defaultTab, true );
			this.requestTemplates( this.defaultTab );
			this.setPreview( 'initial' );

		},

		requestTemplates: function( tabName ) {

			var self = this,
				tab  = self.tabs[ tabName ];

			self.setFilter( 'category', false );

			if ( tab.data.templates && tab.data.categories ) {
				self.layout.showTemplatesView( tab.data.templates, tab.data.categories, tab.data.keywords );
			} else {
				$.ajax({
					url: ajaxurl,
					type: 'get',
					dataType: 'json',
					data: {
						action: 'bew_builder_get_templates',
						tab: tabName,
					},
					success: function( response ) {

						var templates  = new BewBuilderViews.LibraryCollection( response.data.templates ),
							categories = new BewBuilderViews.CategoriesCollection( response.data.categories );

						self.tabs[ tabName ].data = {
							templates: templates,
							categories: categories,
							keywords: response.data.keywords
						};

						self.layout.showTemplatesView( templates, categories, response.data.keywords );
					}
				});
			}

		},

		closeModal: function() {
			this.getModal().hide();
		},

		getModal: function() {

			if ( ! this.modal ) {
				this.modal = elementor.dialogsManager.createWidget( 'lightbox', {
					id: 'bew-template-library-modal',
					closeButton: false
				} );
			}

			return this.modal;

		}

	};

	$( window ).on( 'elementor:init', BewBuilderEditor.init );

})( jQuery );
